    @Override
    public boolean aplicavel(ContextoCupom contexto) {
        return contexto.subtotal().compareTo(MINIMO_PRODUTOS) >= 0;
    }

    @Override
    public BigDecimal desconto(ContextoCupom contexto) {
        return Dinheiro.centavos(DESCONTO);
    }
}
