import java.math.*;
public class Calc {
  static MathContext MC = new MathContext(34, RoundingMode.HALF_EVEN);
  static BigDecimal c(BigDecimal x){return x.setScale(2,RoundingMode.HALF_EVEN);}
  public static void main(String[] a){
    BigDecimal i = new BigDecimal("0.0199");
    for (String[] t : new String[][]{{"474.46","6"},{"425.30","6"},{"1500.00","12"}}) {
      BigDecimal total=new BigDecimal(t[0]); int n=Integer.parseInt(t[1]);
      BigDecimal fator=BigDecimal.ONE.add(i).pow(n,MC);
      BigDecimal div=BigDecimal.ONE.subtract(BigDecimal.ONE.divide(fator,MC));
      BigDecimal p=c(total.multiply(i).divide(div,MC));
      BigDecimal tf=c(p.multiply(BigDecimal.valueOf(n)));
      System.out.println(total+" "+n+" parcela="+p+" totalFinal="+tf+" ajuste="+tf.subtract(total));
    }
  }
}
