    @Nested
    class Imposto {

        @Test
        void aliquota_por_regiao_sobre_produtos_com_desconto() {
            assertThat(impostoDe("SUDESTE")).isEqualByComparingTo("12.00");
            assertThat(impostoDe("SUL")).isEqualByComparingTo("11.00");
            assertThat(impostoDe("CENTRO_OESTE")).isEqualByComparingTo("9.00");
            assertThat(impostoDe("NORTE")).isEqualByComparingTo("7.00");
            assertThat(impostoDe("NORDESTE")).isEqualByComparingTo("7.00");
        }

        /** Produtos 1000,00 com 10% de cupom: base do imposto e 900,00. */
        private BigDecimal impostoDe(String regiao) {
            return calculadora.calcular(pedido("RETIRADA_LOJA", "BEMVINDO10", "BOLETO", null,
                    "BRONZE", regiao, item("Mala", "1000.00", 1, "1.00"))).imposto();
        }
    }

